def evolve(state: str, offsets: list[int], t: int) -> str:
    if t == 0:
        return state

    n = len(state)
    mask = (1 << n) - 1
    value = int(state, 2)
    shifts = [d % n for d in offsets]

    while t:
        if t & 1:
            updated = 0
            for d in shifts:
                updated ^= ((value << d) & mask) | (value >> (n - d))
            value = updated

        t >>= 1
        shifts = [(2 * d) % n for d in shifts]

    return format(value, f"0{n}b")
